-- The schema BizFlow 2.1 created with its own runner (before Drizzle). Used to test adoption.
-- ---------- Accounts, logins and billing ----------

CREATE TABLE accounts (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  business_name TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

CREATE TABLE users (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id    BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  name          TEXT NOT NULL,
  email         TEXT NOT NULL,            -- stored lower-cased (normalizeEmail)
  password_hash TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner')),
  created_at    TEXT NOT NULL
);
CREATE UNIQUE INDEX users_email ON users (lower(email));
CREATE INDEX users_account ON users (account_id);

CREATE TABLE sessions (
  id         TEXT PRIMARY KEY,            -- SHA-256 of the cookie token, never the token itself
  user_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_expires ON sessions (expires_at);

CREATE TABLE password_resets (
  id         TEXT PRIMARY KEY,            -- SHA-256 of the emailed token
  user_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  used_at    TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX password_resets_user ON password_resets (user_id);

-- One row per account. Access is allowed while status is trialing/active and
-- the relevant end date is in the future (see services/billing.ts).
CREATE TABLE subscriptions (
  account_id             BIGINT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
  status                 TEXT NOT NULL CHECK (status IN ('trialing','active','past_due','canceled')),
  provider               TEXT CHECK (provider IN ('stripe','bkash')),
  trial_ends_at          TEXT,
  current_period_end     TEXT,
  cancel_at_period_end   BOOLEAN NOT NULL DEFAULT false,
  stripe_customer_id     TEXT UNIQUE,
  stripe_subscription_id TEXT UNIQUE,
  updated_at             TEXT NOT NULL
);

-- Ledger of subscription payments from either provider.
CREATE TABLE billing_payments (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id   BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  provider     TEXT NOT NULL CHECK (provider IN ('stripe','bkash')),
  provider_ref TEXT NOT NULL,             -- Stripe invoice id or bKash paymentID
  trx_id       TEXT NOT NULL DEFAULT '',  -- bKash transaction id shown to the customer
  amount       BIGINT NOT NULL CHECK (amount >= 0),
  currency     TEXT NOT NULL,
  status       TEXT NOT NULL CHECK (status IN ('pending','paid','failed','cancelled')),
  period_start TEXT,
  period_end   TEXT,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  UNIQUE (provider, provider_ref)
);
CREATE INDEX billing_payments_account ON billing_payments (account_id, created_at DESC);

-- Webhook ids already processed, so retries are harmless.
CREATE TABLE webhook_events (
  provider    TEXT NOT NULL,
  event_id    TEXT NOT NULL,
  received_at TEXT NOT NULL,
  PRIMARY KEY (provider, event_id)
);

-- ---------- Business records (scoped by account_id) ----------

CREATE TABLE settings (
  account_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  key        TEXT NOT NULL,
  value      JSONB NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (account_id, key)
);

CREATE TABLE customers (
  account_id  BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
  name        TEXT NOT NULL,
  company     TEXT NOT NULL DEFAULT '',
  email       TEXT NOT NULL DEFAULT '',
  phone       TEXT NOT NULL DEFAULT '',
  address     TEXT NOT NULL DEFAULT '',
  city        TEXT NOT NULL DEFAULT '',
  country     TEXT NOT NULL DEFAULT '',
  tax_id      TEXT NOT NULL DEFAULT '',
  notes       TEXT NOT NULL DEFAULT '',
  archived_at TEXT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  PRIMARY KEY (account_id, id)
);
CREATE INDEX customers_name ON customers (account_id, lower(name));

-- Quotations and invoices share one table; kind decides which status set applies.
CREATE TABLE documents (
  account_id         BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  id                 BIGINT GENERATED BY DEFAULT AS IDENTITY,
  kind               TEXT NOT NULL CHECK (kind IN ('quotation','invoice')),
  number             TEXT NOT NULL,
  status             TEXT NOT NULL,
  customer_id        BIGINT NOT NULL,
  issue_date         TEXT NOT NULL,
  due_date           TEXT,                -- invoice: payment due; quotation: valid until
  currency           TEXT NOT NULL CHECK (currency IN ('BDT','USD')),
  subtotal           BIGINT NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
  discount_total     BIGINT NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
  tax_total          BIGINT NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
  total              BIGINT NOT NULL DEFAULT 0 CHECK (total >= 0),
  amount_paid        BIGINT NOT NULL DEFAULT 0 CHECK (amount_paid >= 0 AND amount_paid <= total),
  notes              TEXT NOT NULL DEFAULT '',
  terms              TEXT NOT NULL DEFAULT '',
  source_document_id BIGINT,              -- invoice created from this quotation
  sent_at            TEXT,
  paid_at            TEXT,
  cancelled_at       TEXT,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  PRIMARY KEY (account_id, id),
  UNIQUE (account_id, kind, number),
  FOREIGN KEY (account_id, customer_id) REFERENCES customers (account_id, id),
  FOREIGN KEY (account_id, source_document_id) REFERENCES documents (account_id, id)
);
CREATE INDEX documents_customer ON documents (account_id, customer_id);
CREATE INDEX documents_kind_status ON documents (account_id, kind, status);
CREATE UNIQUE INDEX documents_one_invoice_per_quotation
  ON documents (account_id, source_document_id) WHERE source_document_id IS NOT NULL;

CREATE TABLE document_items (
  account_id     BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY,
  document_id    BIGINT NOT NULL,
  position       INTEGER NOT NULL,
  description    TEXT NOT NULL,
  quantity_milli BIGINT NOT NULL CHECK (quantity_milli > 0),
  unit_price     BIGINT NOT NULL CHECK (unit_price >= 0),
  discount_type  TEXT NOT NULL CHECK (discount_type IN ('percent','amount')),
  discount_value BIGINT NOT NULL DEFAULT 0 CHECK (discount_value >= 0),
  tax_name       TEXT NOT NULL DEFAULT '',
  tax_rate_bps   INTEGER NOT NULL DEFAULT 0 CHECK (tax_rate_bps >= 0),
  line_total     BIGINT NOT NULL CHECK (line_total >= 0),
  PRIMARY KEY (account_id, id),
  FOREIGN KEY (account_id, document_id) REFERENCES documents (account_id, id) ON DELETE CASCADE
);
CREATE INDEX document_items_document ON document_items (account_id, document_id, position);

CREATE TABLE payments (
  account_id  BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
  invoice_id  BIGINT NOT NULL,
  amount      BIGINT NOT NULL CHECK (amount > 0),
  paid_at     TEXT NOT NULL,
  method      TEXT NOT NULL,
  reference   TEXT NOT NULL DEFAULT '',
  note        TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL,
  PRIMARY KEY (account_id, id),
  FOREIGN KEY (account_id, invoice_id) REFERENCES documents (account_id, id)
);
CREATE INDEX payments_invoice ON payments (account_id, invoice_id);
CREATE INDEX payments_paid_at ON payments (account_id, paid_at);

CREATE TABLE follow_ups (
  account_id   BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY,
  title        TEXT NOT NULL,
  note         TEXT NOT NULL DEFAULT '',
  due_date     TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','completed')),
  customer_id  BIGINT,
  document_id  BIGINT,
  completed_at TEXT,
  created_at   TEXT NOT NULL,
  PRIMARY KEY (account_id, id),
  FOREIGN KEY (account_id, customer_id) REFERENCES customers (account_id, id),
  FOREIGN KEY (account_id, document_id) REFERENCES documents (account_id, id) ON DELETE SET NULL (document_id)
);
CREATE INDEX follow_ups_due ON follow_ups (account_id, status, due_date);

CREATE TABLE activities (
  account_id  BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY,
  type        TEXT NOT NULL,
  message     TEXT NOT NULL,
  customer_id BIGINT,
  document_id BIGINT,
  created_at  TEXT NOT NULL,
  PRIMARY KEY (account_id, id),
  FOREIGN KEY (account_id, customer_id) REFERENCES customers (account_id, id),
  FOREIGN KEY (account_id, document_id) REFERENCES documents (account_id, id) ON DELETE SET NULL (document_id)
);
CREATE INDEX activities_created ON activities (account_id, created_at DESC);
CREATE INDEX activities_customer ON activities (account_id, customer_id);
